EXTRAS = [
dict(n=71, gr='prescont', vb='run,read,play,eat,talk',
 c1="Agora mesmo|O present continuous (be + -ing) descreve o que está acontecendo agora: 'I'm reading'. Palavras-chave: now, right now, at the moment, today.",
 c2="Observar pessoas|Em inglês, 'people-watching' é observar as pessoas na rua. Muitos escritores fazem isso para criar personagens. É um ótimo exercício de vocabulário: descreva o que cada um está fazendo.",
 ar=("A sunny afternoon","It is Saturday afternoon in the park. The sun is shining and a warm wind is blowing. Children are playing soccer on the grass. A man is reading a newspaper under a tree. A woman is walking her dog. Two friends are eating ice cream and laughing. A band is playing music, and a girl is dancing in front of the stage. Kai and Jade sit on a bench and watch everything. \"What a beautiful day,\" says Jade. \"Everybody is so happy,\" says Kai.","Uma tarde ensolarada no parque cheia de pessoas fazendo coisas.","Quem está sob a árvore?=A man reading|A woman dancing|A boy running;;O que a banda faz?=Playing music|Eating|Sleeping"),
 ex="What's going on?=O que está acontecendo?~Pergunta|I'm working on it.=Estou trabalhando nisso.~Em andamento|You're pulling my leg!=Você está de brincadeira!~Brincadeira|It's raining cats and dogs.=Está chovendo muito.~Clima|Look who's talking!=Olha quem fala!~Ironia",
 tf="She is running é presente contínuo.=T|They playing é correto.=F|Kai e Jade estão no parque.=T|Está chovendo no parque.=F",
 odd="running,reading,eating,table=table|now,today,right now,yesterday=yesterday"),
dict(n=72, gr='simvscont', vb='work,wear,drink,write,stay',
 c1="Hábito x momento|Compare: 'I work at a bank' (rotina) e 'I'm working at home today' (hoje). Em inglês, 'usually' pede present simple e 'now' pede present continuous.",
 c2="Trabalho remoto|Em inglês, 'to work from home' é trabalhar de casa. 'Remote work' é trabalho remoto e 'hybrid' é misto. Muitas empresas usam 'Zoom' ou 'Teams' para reuniões.",
 ar=("A different day","Ivan usually works in a big office with five colleagues. He drinks coffee, answers emails and goes to meetings. Today is different: he is working from home because he is writing a long report. He is wearing a T-shirt and drinking tea. The house is quiet and he is very focused. At noon he is making a sandwich in his own kitchen. \"I usually eat in the canteen,\" he says. \"Today I'm eating with my cat.\" He likes the quiet, but he misses his colleagues.","Ivan trabalha de casa hoje, diferente da rotina de escritório.","Onde Ivan trabalha hoje?=At home|At the office|At a cafe;;O que ele bebe hoje?=Tea|Coffee|Juice"),
 ex="Work from home=Trabalhar de casa~Home office|I'm swamped.=Estou atolado.~Muito trabalho|Take a break.=Faça uma pausa.~Descanso|I'm on a call.=Estou em uma ligação.~Trabalho|Let's touch base.=Vamos conversar.~Trabalho",
 tf="Usually pede present simple.=T|Now pede present continuous.=T|Ivan trabalha hoje no escritório.=F|Ivan bebe chá hoje.=T",
 odd="usually,always,often,now=now|working,writing,drinking,work=work"),
dict(n=73, gr='polite2', vb='send,check,meet,call,finish',
 c1="E-mails no escritório|E-mails profissionais são curtos e claros. Frases úteis: 'I'm writing to…', 'Please find attached…', 'I look forward to hearing from you'. Assuntos claros ajudam a ser lido.",
 c2="Reuniões|Em inglês, 'agenda' é a pauta, 'minutes' é a ata, 'deadline' é o prazo e 'follow-up' é o acompanhamento. Reuniões produtivas têm 'action points' no fim.",
 ar=("Pia's first week","Pia starts a new job on Monday. Max introduces her to the team. She has a desk by the window and a new laptop. Her first task is to write a short report. \"What's the deadline?\" she asks. \"Friday,\" says Max. On Tuesday there is a team meeting at ten o'clock. Everybody welcomes her and shares ideas. In the afternoon she sends her first email to a client. By Friday Pia feels part of the team. \"It's a great place,\" she tells her mother on the phone.","A primeira semana de Pia no escritório.","Onde fica a mesa de Pia?=By the window|At the door|In the kitchen;;Quando é o prazo?=Friday|Monday|Tomorrow"),
 ex="Let's get down to business.=Vamos aos negócios.~Reunião|I'll keep you posted.=Eu te mantenho informado.~Atualizar|Let's wrap up.=Vamos encerrar.~Reunião|Could you send me a reminder?=Poderia me enviar um lembrete?~Pedir|I'm swamped.=Estou atolado.~Ocupado",
 tf="Deadline é prazo.=T|A reunião é na sexta.=F|Pia tem uma mesa perto da janela.=T|Max é a cliente.=F",
 odd="meeting,report,deadline,pizza=pizza|desk,laptop,chair,beach=beach"),
dict(n=74, gr='job', vb='apply,hire,work,learn,start',
 c1="Currículo em inglês|'Resume' (EUA) ou 'CV' (UK) é o currículo. Tem 'education' (formação), 'experience' (experiência) e 'skills' (habilidades). Use verbos de ação: managed, created, improved.",
 c2="Entrevista de emprego|Os recrutadores adoram a pergunta: 'Tell me about yourself.' Responda em 1 minuto: quem você é, o que fez e por que quer a vaga. Sorria e agradeça no final.",
 ar=("A new baker","Sam wants to work at Fatima's bakery. He arrives at nine for the interview with a clean shirt and a big smile. Fatima asks, \"Tell me about yourself.\" Sam says, \"I'm twenty-three years old. I worked in a café for two years and I love bread.\" Fatima likes his honesty. \"When can you start?\" she asks. \"Tomorrow, if you want!\" Fatima laughs and offers him a part-time job. Sam shakes her hand and says, \"Thank you for your time.\" He starts the next morning at six o'clock.","Sam consegue emprego na padaria depois de uma entrevista honesta.","Que vaga Sam consegue?=Part-time|Full-time|Weekend only;;A que horas começa?=Six|Nine|Noon"),
 ex="Tell me about yourself.=Fale sobre você.~Entrevista|I'm a quick learner.=Aprendo rápido.~Habilidade|I'm a team player.=Trabalho bem em equipe.~Habilidade|I look forward to hearing from you.=Aguardo seu retorno.~Fim|It was a pleasure meeting you.=Foi um prazer conhecê-lo.~Fim",
 tf="Resume é currículo.=T|Sam é baker.=F|Part-time é meio período.=T|Fatima oferece o emprego.=T",
 odd="interview,resume,experience,cake=cake|apply,hire,start,table=table"),
dict(n=75, gr='social', vb='write,send,reply,attach,confirm',
 c1="Dear e Hi|'Dear Mr. Brown' é formal; 'Hi Omar' é informal. Para fechar: 'Best regards', 'Kind regards' (formal) ou 'Cheers', 'Thanks' (informal). Nunca esqueça o assunto (subject).",
 c2="E-mail ou mensagem?|Em inglês, e-mail serve para contatos de trabalho e formais; mensagens são para amigos. 'CC' significa cópia e 'BCC' cópia oculta. 'Reply all' responde a todos.",
 ar=("An email for a cake","Hana writes an email to Omar's bakery. She types the subject: 'Cake for Saturday'. Then she writes: 'Dear Omar, I'm writing to ask about a chocolate cake for Saturday. We are twenty people. Could you tell me the price? Please confirm by email. Thank you. Best regards, Hana.' She reads it twice and clicks send. Omar answers in ten minutes: 'Dear Hana, the cake is eighty dollars. See you on Saturday! Best, Omar.' Hana smiles. An email, a cake and a party, all in one morning.","Hana pede um bolo por e-mail e recebe resposta rápida.","Quando é a festa?=On Saturday|On Monday|On Friday;;Quanto tempo Omar leva para responder?=Ten minutes|One day|One hour"),
 ex="I'm writing to…=Escrevo para…~E-mail|Please find attached…=Segue anexo…~E-mail|Looking forward to your reply.=Aguardo sua resposta.~E-mail|Best regards,=Atenciosamente,~Fim|Sorry for the delay.=Desculpe a demora.~Resposta",
 tf="Dear é uma abertura formal.=T|BCC é cópia aberta.=F|Hana pede um bolo de chocolate.=T|O bolo custa vinte dólares.=F",
 odd="dear,regards,subject,pizza=pizza|send,reply,attach,table=table"),
dict(n=76, gr='compl', vb='complain,change,fix,apologize,refund',
 c1="Reclamar com classe|'I'm afraid' e 'I'm sorry to say' suavizam a reclamação. Termine com um pedido: 'Could you…?'. Gentileza resolve mais rápido do que gritos.",
 c2="O cliente tem razão|Em inglês, o ditado 'The customer is always right' vem do início do século XX. Hoje muitas empresas têm 'customer service' (serviço de atendimento) e aceitam reembolso (refund).",
 ar=("A good solution","Elif goes to Remy's restaurant for lunch. The soup is cold, so she complains politely. \"Excuse me,\" she says to the waiter, \"I'm afraid the soup is cold. Could you change it, please?\" Remy comes to the table. \"I'm so sorry,\" he says. \"I'll bring a hot one right away.\" He also offers her a free dessert. Elif smiles and leaves a big tip. She says, \"Good service is the best seasoning.\" Remy bows and goes back to the kitchen, happy.","Elif reclama com educação e Remy resolve com simpatia.","O que Remy oferece?=A free dessert|A discount card|A table;;O que Elif deixa?=A big tip|A note|Nothing"),
 ex="I'm afraid there's a problem.=Receio que haja um problema.~Reclamar|I'd like a refund.=Gostaria de reembolso.~Reclamar|There must be a mistake.=Deve haver um engano.~Reclamar|I'm sorry about that.=Sinto muito por isso.~Atendente|We'll sort it out.=Vamos resolver.~Atendente",
 tf="I'm afraid suaviza uma reclamação.=T|Refund é reembolso.=T|A sopa estava quente.=F|Remy oferece sobremesa grátis.=T",
 odd="refund,complaint,manager,pizza=pizza|cold,wrong,broken,happy=happy"),
dict(n=77, gr='imper', vb='call,help,stay,hurry,rescue',
 c1="Números de emergência|Nos EUA e no Canadá é 911. No Reino Unido é 999. Na União Europeia, 112. No Brasil, 192 (SAMU) e 193 (bombeiros). Aprenda o número local antes de viajar.",
 c2="Primeiros socorros|Em inglês, 'first aid' são os primeiros socorros e 'CPR' é a ressuscitação cardiopulmonar. 'Stay calm' (fique calmo) é a primeira frase que ouvimos em emergências.",
 ar=("A quick response","Last Friday there was an accident on Maple Street. A bicycle hit a car. The cyclist fell down and shouted, \"Help!\" Dina saw it from her window and called the emergency number. \"Emergency services,\" said the voice. \"There's an accident on Maple Street, in front of number twelve,\" said Dina. \"Stay calm. Help is on the way.\" The ambulance arrived in five minutes. The paramedics helped the cyclist and everybody felt relieved. He only had a small cut on his arm.","Um acidente é resolvido rapidamente graças à ligação de Dina.","Quem chamou a emergência?=Dina|Pete|Mia;;Quanto a ambulância demorou?=Five minutes|One hour|Ten minutes"),
 ex="Call 911!=Ligue 911!~Emergência|Help is on the way.=A ajuda está a caminho.~Resposta|Stay calm.=Fique calmo.~Emergência|Is everyone OK?=Todos estão bem?~Pergunta|It's an emergency!=É uma emergência!~Alerta",
 tf="911 é o número de emergência nos EUA.=T|Stay calm é fique calmo.=T|O acidente envolveu um carro e uma bicicleta.=T|A ambulância demorou uma hora.=F",
 odd="ambulance,police,fire,pizza=pizza|help,call,hurry,table=table"),
dict(n=78, gr='opinion', vb='think,like,watch,enjoy,give',
 c1="Dar opinião|Em inglês, 'I think…' e 'In my opinion…' dão opinião. Para suavizar: 'I tend to think…', 'It seems to me…'. Use 'because' para justificar.",
 c2="Cinema e estrelas|Os críticos de cinema dão 'stars' (estrelas): cinco é excelente e uma é péssimo. Em inglês, 'a must-see' é um filme imperdível e 'a flop' é um fracasso de bilheteria.",
 ar=("Movie night debate","After the movie, Will and Isla go to a cafe and talk about it for an hour. Will loved the story and the acting. \"I think it's the best movie of the year,\" he says. Isla liked the music but thought the ending was boring. \"In my opinion, it was too long,\" she says. They disagree, but they respect each other's opinion. They look at the reviews on their phones: four stars! At the end they give the movie three and a half stars and order a second coffee.","Dois amigos debatem o filme e chegam a três estrelas e meia.","O que Isla gostou?=The music|The ending|The popcorn;;Quantas estrelas dão?=Three and a half|Five|One"),
 ex="It's a must-see.=É imperdível.~Filme|It was a total flop.=Foi um fracasso.~Filme|It's right up my alley.=É bem o meu estilo.~Gosto|I couldn't agree more.=Concordo plenamente.~Concordar|That's not my cup of tea.=Não é a minha praia.~Discordar",
 tf="In my opinion dá opinião.=T|A-star é muito ruim.=F|Isla achou o final chato.=T|Will odiou o filme.=F",
 odd="movie,story,acting,spoon=spoon|boring,exciting,interesting,table=table"),
dict(n=79, gr='opinion', vb='agree,disagree,listen,decide,explain',
 c1="Neither do I|Para concordar com frases afirmativas, use 'So do I' ou 'Me too'. Para concordar com negativas, use 'Neither do I' ou 'Me neither'. É uma ótima ferramenta de conversação.",
 c2="Debates|Os debates escolares em países de língua inglesa têm formato rígido: tempo definido, 'opening statement' (abertura) e 'rebuttal' (réplica). Debater ajuda a pensar e a falar com clareza.",
 ar=("The debate","In the classroom, Mina and Hiro debate: is it better to study in the morning or at night? Mina says, \"Mornings are fresh and quiet. I can focus.\" Hiro says, \"I don't agree. Nights are calm and no one disturbs me.\" They listen to each other and ask questions. \"That's a good point,\" says Mina. \"I don't like noise either.\" In the end, they find a compromise: study in the afternoon with a cup of tea. Mia, the teacher, smiles and says, \"A good debate has no losers.\"","Mina e Hiro debatem com respeito e chegam a um meio-termo.","Quem prefere a manhã?=Mina|Hiro|Mia;;O que acompanha o estudo?=Tea|Music|Snacks"),
 ex="I couldn't agree more.=Concordo plenamente.~Concordar|I see your point, but…=Entendo, mas…~Discordar|Let's agree to disagree.=Vamos concordar em discordar.~Fim de debate|That's fair enough.=É justo.~Concordar|You've got a point.=Você tem razão.~Concordar",
 tf="So do I concorda com afirmativas.=T|Neither do I concorda com negativas.=T|Mina prefere estudar à noite.=F|Eles chegam a um acordo.=T",
 odd="agree,disagree,compromise,tea=tea|morning,night,afternoon,chair=chair"),
dict(n=80, gr='prescont', vb='write,answer,have,work,prepare',
 c1="Revisão: agora e trabalho|Misture o que aprendeu: 'I'm writing a report, I usually work at the office, in my opinion it's too long.' Frases com vários tempos mostram fluência.",
 c2="Equipes|Em inglês, 'team' é equipe e 'teamwork' é trabalho em equipe. 'The whole is greater than the sum of its parts': o todo vale mais que a soma das partes. Boas equipes se comunicam.",
 ar=("A busy morning","At the office, everybody is busy. Pia is writing a long report for a client. Will is answering emails and drinking coffee. Mia is preparing the meeting. They disagree about the time, but they compromise: the meeting is at eleven. At the meeting, each person explains what they are doing. \"In my opinion, we are doing a great job,\" says Mia. At noon they eat lunch together and talk about the weekend. \"Teamwork makes the dream work,\" says Will. Everybody laughs.","Uma manhã ocupada termina com reunião e almoço juntos.","Quem prepara a reunião?=Mia|Pia|Will;;Quando almoçam?=At noon|At ten|At six"),
 ex="Teamwork makes the dream work.=Trabalho em equipe realiza sonhos.~Frase motivacional|Let's keep in touch.=Vamos manter contato.~Despedida|It's a deal.=Fechado.~Acordo|I'm on it.=Estou cuidando disso.~Trabalho|Good job!=Bom trabalho!~Elogio",
 tf="Teamwork é trabalho em equipe.=T|A reunião foi marcada para as onze.=T|Will está escrevendo um relatório.=F|Eles almoçam juntos.=T",
 odd="meeting,report,team,pizza=pizza|writing,answering,preparing,work=work"),
]
